public class PriorityDemo extends Thread {
    public static void main(String[] args) {
        PriorityDemo t1 = new PriorityDemo();
        PriorityDemo t2 = new PriorityDemo();
        PriorityDemo t3 = new PriorityDemo();

        t1.setName("One");
        t2.setName("Two");
        t3.setName("Three");

        t1.setPriority(4);
        t2.setPriority(Thread.MAX_PRIORITY);
        t3.setPriority(8);

        t1.start();
        t2.start();
        t3.start();
    }

    public void run() {
        System.out.println(Thread.currentThread().getName() + " is running.");
    }
}

public class JoinDemo extends Thread {
    public static void main(String[] args) {
        JoinDemo t1 = new JoinDemo();
        JoinDemo t2 = new JoinDemo();
        t1.start();

        // start the 2nd thread after 2 seconds, or sooner if t1 finishes
        try {
            t1.join(2000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        t2.start();

        // wait for both threads to terminate
        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Thread-0 is alive: " + t1.isAlive());
        System.out.println("Thread-1 is alive: " + t2.isAlive());
    }

    public void run() {
        System.out.println(Thread.currentThread().getName() + " is running.");
        try {
            Thread.sleep(3000);          // suspends this thread for 3 seconds
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        System.out.println(Thread.currentThread().getName() + " has ended.");
    }
}
